The product will be delivered. That is the Mafia promise. And a promise means nothing without verification. Here is the test suite that ensures our checkout operation runs with the precision of a well-managed franchise.

```typescript
// Checkout.test.tsx
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock our dependencies - we control our supply chain
const mockCartContext = {
  items: [{ id: '1', name: 'Protection Services', price: 99.99 }],
  total: 99.99,
  clearCart: vi.fn(),
};

const mockPaymentContext = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCartContext,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => mockPaymentContext,
}));

describe('Checkout - The Franchise Standards', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockPaymentContext.processPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy Path - Complete Transaction', () => {
    it('completes full checkout flow from shipping to confirmation', async () => {
      const onComplete = vi.fn();
      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Mafia Lane');
      await user.type(screen.getByLabelText(/city/i), 'New Brooklyn');
      await user.selectOptions(screen.getByLabelText(/state/i), 'NY');
      await user.type(screen.getByLabelText(/zip code/i), '12345');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Enzo Strozzi');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/protection services/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-12345')).toBeInTheDocument();
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  describe('Form Validation - We Have Standards', () => {
    it('displays street address error when empty', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    });

    it('validates ZIP code format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'invalid');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });

    it('validates card number is 16 digits', async () => {
      render(<Checkout />);
      // Navigate to payment
      await fillShippingForm(user);
      await user.type(screen.getByLabelText(/card number/i), '123');
      await user.click(screen.getByRole('button', { name: /review order/i }));
      expect(screen.getByText(/valid 16-digit card/i)).toBeInTheDocument();
    });
  });

  describe('Error States - When Deals Go Wrong', () => {
    it('displays payment error and allows retry', async () => {
      mockPaymentContext.processPayment.mockRejectedValueOnce(new Error('Card declined'));
      render(<Checkout />);
      await completeToReview(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));
      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);

      // Retry succeeds
      mockPaymentContext.processPayment.mockResolvedValueOnce({ orderId: 'ORD-99999' });
      await user.click(screen.getByRole('button', { name: /place order/i }));
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
    });
  });

  describe('Loading States - Patience Is Professional', () => {
    it('disables buttons and shows loading during submission', async () => {
      mockPaymentContext.processPayment.mockImplementation(() => new Promise(() => {}));
      render(<Checkout />);
      await completeToReview(user);

      await user.click(screen.getByRole('button', { name: /place order/i }));

      expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
      expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
    });
  });

  describe('Edge Cases - The Unexpected', () => {
    it('shows empty cart message when no items', () => {
      mockCartContext.items = [];
      render(<Checkout onCancel={vi.fn()} />);
      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });
  });

  describe('Accessibility - Everyone Pays', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });

    it('marks invalid fields with aria-invalid', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });
  });
});

// Helper functions - our trusted associates
async function fillShippingForm(user) {
  await user.type(screen.getByLabelText(/street/i), '123 Test St');
  await user.type(screen.getByLabelText(/city/i), 'TestCity');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip/i), '90210');
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function completeToReview(user) {
  await fillShippingForm(user);
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Test User');
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
